  color: #fff;
  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 6px;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s;
}
#theme-toggle:hover { background: rgba(255,255,255,0.22); }

/* ── Page content ── */
.page-content {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 20px 48px;
}

/* ── Description card ── */
.desc-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 20px 24px;
  margin-bottom: 20px;
  box-shadow: var(--shadow);
}
.desc-card h1 {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 6px;
}
.desc-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}
.desc-card a { color: var(--link-color); }

/* ── API tabs (matches admin-tabs exactly) ── */
.api-tabs {
  display: flex;
  gap: 2px;
  margin-bottom: 16px;
  background: var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  width: fit-content;
}
.api-tab {
  padding: 10px 28px;
  border: none;
  background: var(--bg-card);
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 0.95em;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.api-tab:hover { background: var(--hover-bg); color: var(--text-primary); }
.api-tab.active { background: #2196F3; color: #fff; }

/* ── Swagger containers ── */
.swagger-panel { display: none; }
.swagger-panel.active { display: block; }
.swagger-wrap {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

/* ── Swagger UI overrides — shared for both panels ── */
.swagger-wrap .swagger-ui { background: var(--bg-card) !important; }
.swagger-wrap .swagger-ui .info .title,
.swagger-wrap .swagger-ui .info h1,
.swagger-wrap .swagger-ui .info h2 { color: var(--text-primary) !important; }
