// ============================================================
// H3 Hexagonal Grid Overlay
// ============================================================

/**
 * Maps a µSv/h dose rate to a fill colour for H3 hex cells.
 * Palette matches the existing marker colour scale.
 */
function h3DoseColor(dose) {
  if (dose < 0.05)  return { color: '#2ecc71', opacity: 0.6 };  // green  — background
  if (dose < 0.10)  return { color: '#f1c40f', opacity: 0.65 }; // yellow
  if (dose < 0.30)  return { color: '#e67e22', opacity: 0.7 };  // orange
  if (dose < 1.00)  return { color: '#e74c3c', opacity: 0.75 }; // red
  return               { color: '#9b59b6', opacity: 0.85 };      // purple — extreme
}

/**
 * Fetch /api/h3grid for current viewport and redraw the H3 overlay layer.
 */
function refreshH3Grid() {
  if (!h3GridActive || !map || typeof h3 === 'undefined') return;

  // Cancel any in-flight request
  if (h3GridFetchCtrl) h3GridFetchCtrl.abort();
  h3GridFetchCtrl = new AbortController();

  const bounds = map.getBounds();
  const zoom   = map.getZoom();
  const params = new URLSearchParams({
    zoom:   zoom,
    minLat: bounds.getSouth(),
    minLon: bounds.getWest(),
