	}

	var req struct {
		Password string `json:"password"`
		TrackID  string `json:"track_id"`
		Name     string `json:"name"`
		Username string `json:"username"`
		Notes    string `json:"notes"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.TrackID == "" {
