			"message": fmt.Sprintf("Deleted %d of %d tracks", deleted, len(req.TrackIDs)),
			"deleted": deleted,
			"errors":  errors,
		})
	} else {
		json.NewEncoder(w).Encode(map[string]interface{}{
			"status":  "success",
			"message": "All tracks deleted successfully",
			"deleted": deleted,
		})
	}
}

