/**
 * Maps a µSv/h dose rate to a fill colour for H3 hex cells.
 * Uses the exact same schemeSafecast colour scale as individual markers.
 */
function h3DoseColor(dose) {
  // Mirror of schemeSafecast defined above
  const scheme = [
    { uSv: 0.03,  color: [0,   0,   139] },
    { uSv: 0.05,  color: [0,   71,  171] },
    { uSv: 0.08,  color: [65,  105, 225] },
    { uSv: 0.12,  color: [135, 206, 250] },
    { uSv: 0.16,  color: [0,   191, 255] },
    { uSv: 0.23,  color: [0,   255, 255] },
    { uSv: 0.31,  color: [64,  224, 208] },
    { uSv: 0.43,  color: [147, 112, 219] },
    { uSv: 0.60,  color: [186, 85,  211] },
    { uSv: 0.87,  color: [255, 0,   255] },
    { uSv: 1.31,  color: [255, 20,  147] },
    { uSv: 2.13,  color: [255, 0,   0]   },
    { uSv: 3.99,  color: [255, 69,  0]   },
    { uSv: 10.09, color: [255, 165, 0]   },
    { uSv: 65.54, color: [255, 255, 0]   },
  ];

  if (dose <= scheme[0].uSv) {
    const c = scheme[0].color;
    return { color: `rgb(${c[0]},${c[1]},${c[2]})`, opacity: 0.7 };
  }
  if (dose >= scheme[scheme.length - 1].uSv) {
    const c = scheme[scheme.length - 1].color;
    return { color: `rgb(${c[0]},${c[1]},${c[2]})`, opacity: 0.85 };
  }
  for (let i = 0; i < scheme.length - 1; i++) {
    if (dose >= scheme[i].uSv && dose <= scheme[i + 1].uSv) {
      const t  = (dose - scheme[i].uSv) / (scheme[i + 1].uSv - scheme[i].uSv);
      const lo = scheme[i].color, hi = scheme[i + 1].color;
      const r  = Math.round(lo[0] + (hi[0] - lo[0]) * t);
      const g  = Math.round(lo[1] + (hi[1] - lo[1]) * t);
      const b  = Math.round(lo[2] + (hi[2] - lo[2]) * t);
      return { color: `rgb(${r},${g},${b})`, opacity: 0.7 };
    }
  }
  return { color: 'rgb(255,255,0)', opacity: 0.85 };
}

