// Cap how many raw markers we read per request. At low zoom levels a single
// viewport can contain millions of GPS points; reading them all blocks the DB
// for 20-30 seconds. 150k markers is enough to fill every H3 cell at any
// resolution we use, and keeps response time under ~2 seconds.
const maxMarkers = 150_000

// Use a child context so we can cancel the DB stream once we hit the cap
// without cancelling the HTTP handler itself.
streamCtx, cancelStream := context.WithCancel(r.Context())
defer cancelStream()

markers, errCh := db.StreamMarkersByZoomAndBounds(streamCtx, 0, minLat, minLon, maxLat, maxLon, *dbType)

type cellAcc struct {
	sumDose float64
	maxDose float64
	count   int
}
cells := make(map[h3.Cell]*cellAcc)
read := 0

for m := range markers {
	if m.DoseRate <= 0 {
		continue
	}
	cell, _ := h3.LatLngToCell(h3.NewLatLng(m.Lat, m.Lon), res)
	acc := cells[cell]
	if acc == nil {
		acc = &cellAcc{}
		cells[cell] = acc
	}
	acc.sumDose += m.DoseRate
	acc.count++
	if m.DoseRate > acc.maxDose {
		acc.maxDose = m.DoseRate
	}
	read++
	if read >= maxMarkers {
		cancelStream() // stop the DB query early
		break
	}
}
// Drain remainder so the goroutine can exit.
for range markers {}

// Drain error channel — context cancellation after cap is expected and normal.
if e := <-errCh; e != nil && streamCtx.Err() == nil && r.Context().Err() == nil {
	writeError(w, http.StatusInternalServerError, e.Error())
	return
}

