// PERFORMANCE OPTIMIZATION: Unified marker creation function
// This eliminates 120+ lines of duplicate code between cached and streamed rendering
function createMarkerFromData(m, zoom) {
  const isLive = m.speed < 0;
  let marker;

  if (isLive) {
    // Realtime marker with heartbeat icon
    const nowSec = Date.now() / 1000;
    const icon = buildRealtimeIcon(m, zoom, nowSec);
    if (!icon) return null; // Device older than 24 hours

    // Use pool for div markers
    const leafletIcon = L.divIcon({className:'', html: icon.html, iconSize:[icon.size, icon.size], iconAnchor:[icon.radius, icon.radius]});
    marker = markerPool.getDivMarker(m.lat, m.lon, leafletIcon);

    // Lazy-bind tooltip and popup only on user interaction
    marker.on('mouseover', function() {
      if (!this._tooltip) {
        this.bindTooltip(getTooltipContent(m), {
          direction:'top',
          className:'custom-tooltip',
          offset:[0,-8],
          interactive:true
        });
      }
    });

    // Directly open chart modal on click for realtime sensors
    marker.on('click', function(e) {
      // If picking location for upload, capture coordinates instead
      if (isPickingLocation && pickLocationHandler) {
        map.fire('click', { latlng: L.latLng(m.lat, m.lon) });
        return;
      }
      const deviceID = m.deviceID || (m.trackID ? m.trackID.replace(/^live:/, '') : '');
      if (deviceID) {
        const fallback = {
          device: deviceID,
          name: m.deviceName || '',
          transport: m.transport || '',
          tube: m.tube || '',
          country: m.country || '',
          lat: m.lat || '',
          lon: m.lon || '',
          doseRate: m.doseRate || null,
          date: m.date || null,
        };
        openLiveModal(deviceID, fallback);
      }

